local abs = math.abs
local type = type
local S = SuuUI.UISignals

-- The rounded-rectangle alpha mask, generated by Media/generate_masks.py. Backslashes to match the
-- convention every other texture path in the addon uses.
local ROUND_MASK = "Interface\\AddOns\\SuuUI\\Media\\round-mask"

-- MIRRORS RADIUS_FRAC in Media/generate_masks.py. The mask is stretched over the art, so its corner
-- is a fraction of the frame rather than an absolute length -- and the ring drawn around that art has
-- to use the same fraction, or the two curves disagree and the shallower one occludes the deeper.
-- Change it in the generator, regenerate, and change it here: the two are a contract.
local ROUND_MASK_RADIUS_FRAC = 0.125

local IconMeta = {}
IconMeta.__index = IconMeta

-- Blizzard's icon files bake a bevelled frame into the outer edge of the art, so a raw
-- icon inside a themed border shows two borders. Cropping to the inner span removes it.
-- A fact about the client's assets rather than a design choice, which is why it is a
-- literal here and not a theme token — no theme can change what is in the file.
local TRIM_MIN, TRIM_MAX = 0.07, 0.93

--- Sets the displayed texture. Pass nil to clear it.
-- @param path string|nil
--- Sets the texture, and optionally which part of it to show.
--
-- `coords` is for a glyph on an ATLAS: one sheet holds many icons, so the texture alone is not
-- enough to say which one. It overrides `trim`, because trim crops the bevel Blizzard bakes into
-- its own icon FILES and an atlas of ours has no bevel to crop -- applying both would crop a
-- glyph to a quarter of itself.
-- @param path string|nil
-- @param coords table|nil  { left, right, top, bottom } as 0..1 fractions
function IconMeta:SetIcon(path, coords)
    self._icon:SetTexture(path)
    self._path = path
    if coords then
        self._coords = coords
        self._icon:SetTexCoord(coords[1], coords[2], coords[3], coords[4])
    elseif self._coords then
        -- Explicitly cleared: back to the whole texture, or to the trim if one was asked for.
        self._coords = nil
        if self._trim then
            self._icon:SetTexCoord(TRIM_MIN, TRIM_MAX, TRIM_MIN, TRIM_MAX)
        else
            self._icon:SetTexCoord(0, 1, 0, 1)
        end
    end
end

--- Returns the current texture path.
-- @return string|nil
function IconMeta:GetIcon()
    return self._path
end

--- Sets an explicit size, dropping token-driven sizing.
-- SIZE_CHANGED comes from the frame's own resize hook, not from here.
-- @param w number
-- @param h number
function IconMeta:SetSize(w, h)
    self._autoSize = false
    self._f:SetSize(w, h)
end

-- How far the art sits inside the frame: the border width when there is a border to stay
-- clear of, nothing at all otherwise. Re-stated on a theme change because borderWidth is
-- a token — a value fixed at construction stops tracking it.
function IconMeta:_applyInset()
    local inset = 0
    if self._border then
        inset = SuuUI.Pixel.Line(SuuUI.Theme:GetToken("borderWidth") or 1)
    end
    if self._iconProps.inset ~= inset then
        self._iconProps.inset = inset
        self._box:SetChildProps(self._icon, self._iconProps)
        -- The mask has to move with the art or the rounding drifts off the corner it is rounding.
        if self._maskProps then
            self._maskProps.inset = inset
            self._box:SetChildProps(self._mask, self._maskProps)
        end
    end
end

-- An icon holds no text, so its size comes straight from the token rather than being
-- floored against the font metrics. Skipped when the caller pinned a size.
function IconMeta:_autosize()
    if not self._autoSize then return end
    local size = SuuUI.Theme:GetToken("sizeIcon") or 16
    if abs((self._f:GetWidth() or 0) - size) > 0.5
       or abs((self._f:GetHeight() or 0) - size) > 0.5 then
        self._f:SetSize(size, size)
    end
end

--- Sets the border colour token or literal. No-op on a borderless icon, which has no
--- backdrop to recolour. Lets an icon's edge carry state — a cast bar marks an
--- uninterruptible spell this way — without the caller rebuilding the icon.
-- @param color string|table|false
function IconMeta:SetBorderColor(color)
    if not self._border or self._borderColor == color then return end
    self._borderColor = color
    self:ApplyTheme()
end

--- Tints the ART, leaving the border and the frame alone.
--
-- Separate from SetBorderColor because they answer different questions: a border carries a
-- property OF the thing (a cast is uninterruptible), while a tint on the art carries whether
-- the thing is USABLE right now. An action button needs the second and has no border at all.
--
-- The tint multiplies the texture, so nil -- full white -- is "no tint" rather than "black".
-- @param color string|table|nil  token key, {r,g,b,a} literal, or nil for untinted
-- @param alpha number|nil  optional multiplier applied on top, for dimming without a colour
function IconMeta:SetArtTint(color, alpha)
    local r, g, b, a = 1, 1, 1, 1
    if color ~= nil then
        local c = color
        if type(c) == "string" then c = SuuUI.Theme:GetToken(c) end
        if type(c) == "table" then
            r, g, b = c[1] or 1, c[2] or 1, c[3] or 1
            a = c[4] == nil and 1 or c[4]
        end
    end
    if alpha ~= nil then a = alpha end
    self._artTint = color
    self._artAlpha = alpha
    self._icon:SetVertexColor(r, g, b, a)
end

--- Drains the colour out of the art, as the client does for an unusable action.
--
-- Not every client generation has SetDesaturated on a texture, and the ones that do can
-- refuse it on a machine without the shader; it returns false in that case. The tint is the
-- fallback, so a caller pairing the two still gets a visibly different state either way.
-- @param on bool
-- @return bool  whether the client actually desaturated
function IconMeta:SetArtDesaturated(on)
    self._artDesaturated = on and true or false
    if type(self._icon.SetDesaturated) ~= "function" then return false end
    return self._icon:SetDesaturated(self._artDesaturated) ~= false
end

function IconMeta:ApplyTheme()
    if self._border then
        -- A ROUNDED border is drawn from masked textures, never a backdrop: a backdrop's corners are
        -- its texture's corners, and one underneath would show square corners through the rounding.
        if self._panel then
            self._panel:Refresh()
            self._panel:SetBg("colorBgAlt")
            self._panel:SetBorder(self._borderColor or "colorBorder")
        else
            SuuUI.Backdrop.Apply(self._f, {
                bg     = "colorBgAlt",
                border = self._borderColor or "colorBorder",
            })
        end
    end
    self:_applyInset()
    self:_autosize()
    -- Re-assert the art tint: it may name a token, and a live token edit has to reach an
    -- icon that is already sitting in a tinted state.
    if self._artTint ~= nil or self._artAlpha ~= nil then
        self:SetArtTint(self._artTint, self._artAlpha)
    end
    -- opacityDisabled is user-editable, so re-assert the fade or a live token edit never
    -- reaches an icon that is already sitting disabled.
    self:_applyEnabled()
end

function IconMeta:Destroy()
    S:DisconnectAll(self)
    SuuUI.Events:Off("SUUUI_THEME_CHANGED", self._eid)
    if self._panel then self._panel:Destroy() end
    self._box:Destroy()
    self._f:Hide()
end

-- Fills in GetWidth, GetHeight, IsShown, GetFrame, Show, Hide. SetSize is defined above
-- and survives: it has to clear the token-sizing flag.
SuuUI.Components.InstallBase(IconMeta, "_f")
-- Canonical enabled state: one root-frame fade via the opacityDisabled token.
SuuUI.Components.InstallEnable(IconMeta, "_f")

--- Creates a display-only icon: a texture in a frame, with an optional themed border.
--
-- For a clickable icon use IconButton — this one takes no mouse input, which is what
-- makes it safe to overlay or nest inside something that does.
--
-- Emits SIZE_CHANGED, VISIBILITY_CHANGED, ENABLED_CHANGED.
-- @param props table  { icon, size, w, h, border, borderColor, trim, rounded, radius, coords }
--   rounded: true to draw the border as a rounded surface (Backdrop.Panel). Requires border = true,
--     since there is nothing to round without one. Opt-in rather than default: turning it on for
--     every icon would restyle every aura, action and bag cell in the addon at once.
--   radius: corner radius override; defaults to the borderRadius token.
--   icon:   texture path
--   size:   square size; w/h override it per axis. Omit all three to follow sizeIcon.
--   border: draw the themed border and inset the art inside it (default false)
--   borderColor: token key or literal for that border (default "colorBorder")
--   trim:   crop the baked bevel off a Blizzard icon file (default false)
-- @param parent frame
-- @return table  Icon handle
function SuuUI.Components.Icon(props, parent)
    props = props or {}
    local pinned = props.size or props.w or props.h
    local size   = props.size or SuuUI.Theme:GetToken("sizeIcon") or 16
    local border = props.border == true

    -- The backdrop template only comes along when there is a border to draw AND that border is
    -- square; a plain icon is the texture and nothing else, and a rounded one draws its own surface
    -- from masked textures, which a backdrop underneath would show square corners through.
    local rounded = border and props.rounded == true
    local f = CreateFrame("Frame", nil, parent,
                          (border and not rounded) and "BackdropTemplate" or nil)
    f:SetSize(props.w or size, props.h or props.w or size)

    -- Registered before the host container adopts the frame so the container chains onto
    -- this hook. A parent layout resizes the frame directly and never calls SetSize, so
    -- this is the only place that sees a layout-driven resize.
    local handle
    f:SetScript("OnSizeChanged", function(_, w2, h2)
        if not handle then return end
        S:Emit(handle, S.SIGNALS.SIZE_CHANGED, w2, h2)
    end)

    local box  = SuuUI.Layout:CreateContainer({ host = f, layout = "stack" })
    local icon = f:CreateTexture(nil, "ARTWORK")
    if props.icon then icon:SetTexture(props.icon) end
    -- coords wins over trim: see SetIcon. An atlas glyph has no baked bevel to crop, and doing
    -- both would show a quarter of the glyph.
    if props.coords then
        local c = props.coords
        icon:SetTexCoord(c[1], c[2], c[3], c[4])
    elseif props.trim then
        icon:SetTexCoord(TRIM_MIN, TRIM_MAX, TRIM_MIN, TRIM_MAX)
    end

    local iconProps = { inset = 0 }
    box:Add(icon, iconProps)

    -- ROUNDING THE ART, not just the surface behind it. Backdrop.Panel rounds a bg and a border we
    -- draw ourselves, and for a bag cell that is invisible: the item icon covers the cell edge to
    -- edge, so the corners the player sees are the ART's corners. Measured in game 2026-08-25 --
    -- cells rendered hard square with Panel correctly installed underneath them, which is what makes
    -- this the second half of the same feature rather than a nicety.
    --
    -- A mask multiplies its alpha into the texture it is attached to, so it rounds art we did not
    -- draw and cannot edit. Feature-detected exactly as Backdrop.CircleMask is: no mask API means
    -- square art, a worse look rather than a broken icon.
    --
    -- The mask is added to the SAME container with its OWN props table mirroring the art's, so it
    -- tracks the art's inset -- _applyInset updates both. Sharing one table would be tempting and
    -- wrong: SetChildProps is called per child, so one table would be applied twice under two
    -- different children and the second call would win.
    local maskProps, maskTex
    if rounded and type(f.CreateMaskTexture) == "function"
       and type(icon.AddMaskTexture) == "function" then
        maskTex = f:CreateMaskTexture()
        maskTex:SetTexture(ROUND_MASK)
        maskProps = { inset = 0 }
        box:Add(maskTex, maskProps)
        icon:AddMaskTexture(maskTex)
    end

    local id = "icon_" .. tostring(f)
    handle = setmetatable({
        _f          = f,
        _icon       = icon,
        _box        = box,
        _iconProps  = iconProps,
        _eid        = id,
        _enabled    = true,
        _border     = border,
        _borderColor = props.borderColor or "colorBorder",
        _path       = props.icon,
        _autoSize   = pinned == nil,
        _coords     = props.coords,
        _trim       = props.trim and true or false,
        _mask       = maskTex,
        _maskProps  = maskProps,
    }, IconMeta)

    -- Built BEFORE the first ApplyTheme, which is what paints it: a panel created afterwards would
    -- sit uncoloured until the next theme change.
    if rounded then
        -- radiusFrac rather than the borderRadius token: the art is rounded by a stretched mask whose
        -- corner is proportional, and the ring has to match it exactly. Measured in game -- a token
        -- radius larger than the mask's made the art bulge over the ring and the coloured border
        -- disappear at every corner while looking perfect along the straight edges. An explicit
        -- radius prop still wins, for a caller whose art is not masked.
        handle._panel = SuuUI.Backdrop.Panel(f, {
            radius     = props.radius,
            radiusFrac = (not props.radius) and maskTex and ROUND_MASK_RADIUS_FRAC or nil,
        })
    end

    handle:ApplyTheme()
    SuuUI.Events:On("SUUUI_THEME_CHANGED", function() handle:ApplyTheme() end, id)
    return handle
end
